import * as React from 'react';
const processItemSelection = ({ rowSelection, item, getSubRows, getRowId, }) => {
    let isSelected = true;
    const itemId = getRowId(item);
    const subRows = getSubRows(item) ?? [];
    if (subRows.length > 0) {
        // We cannot use every because it exits early
        // and prevents all items from being checked
        subRows.forEach((subRow) => {
            const isSubRowSelected = processItemSelection({
                item: subRow,
                rowSelection,
                getSubRows,
                getRowId,
            });
            if (!isSubRowSelected) {
                isSelected = false;
            }
        });
    }
    else {
        isSelected = rowSelection[itemId] === true;
    }
    if (isSelected) {
        rowSelection[itemId] = true;
    }
    else if (itemId in rowSelection) {
        delete rowSelection[itemId];
    }
    return isSelected;
};
export const useRowSelectionFixedHandler = ({ rowSelection, setRowSelection, tableData, getSubRows, getRowId, }) => {
    const fixedRowSelectionHandler = React.useCallback((rowSelectionUpdater) => {
        const rowSelectionUpdated = typeof rowSelectionUpdater === 'function'
            ? rowSelectionUpdater(rowSelection)
            : rowSelectionUpdater;
        tableData.forEach((item) => {
            processItemSelection({
                item,
                rowSelection: rowSelectionUpdated,
                getSubRows,
                getRowId,
            });
        });
        setRowSelection(rowSelectionUpdated);
    }, [rowSelection, setRowSelection, tableData, getSubRows, getRowId]);
    return fixedRowSelectionHandler;
};
